import unittest

from author_util import author
from author import mp_table_helpers as tblh


class TestAuthorStdTable(unittest.TestCase):
    def test_std_table_applies_explicit_th_and_td_attrs(self):
        table = author.std_table(
            [[author.hbo("כו״ק"), "Example usage"]],
            arg_to_troh=["Template", "Purpose"],
            tdattrs=[{"class": "template-col"}, {"class": "wide-col"}],
            thattrs=[{"class": "template-col"}, {"class": "wide-col"}],
        )

        rows = table["contents"]
        header_cells = rows[0]["contents"]
        data_cells = rows[1]["contents"]

        self.assertEqual(header_cells[0]["attr"]["class"], "template-col")
        self.assertEqual(header_cells[1]["attr"]["class"], "wide-col")
        self.assertEqual(data_cells[0]["attr"]["class"], "template-col")
        self.assertEqual(data_cells[1]["attr"]["class"], "wide-col")

    def test_std_table_does_not_infer_template_purpose_classes(self):
        table = author.std_table(
            [[author.hbo("כו״ק"), "Example usage"]],
            arg_to_troh=["Template", "Purpose"],
        )

        rows = table["contents"]
        header_cells = rows[0]["contents"]
        data_cells = rows[1]["contents"]

        self.assertNotIn("attr", header_cells[0])
        self.assertNotIn("attr", header_cells[1])
        self.assertNotIn("attr", data_cells[0])
        self.assertNotIn("attr", data_cells[1])

    def test_std_table_does_not_infer_description_wide_col(self):
        table = author.std_table(
            [["header", "string", "Long description"]],
            arg_to_troh=["Key", "Type", "Description"],
        )

        rows = table["contents"]
        header_cells = rows[0]["contents"]
        data_cells = rows[1]["contents"]

        self.assertNotIn("attr", header_cells[2])
        self.assertNotIn("attr", data_cells[2])

    def test_tmpl_purp_table_applies_expected_attrs(self):
        table = tblh.tmpl_purp_table([[author.hbo("כו״ק"), "Example usage"]])

        rows = table["contents"]
        header_cells = rows[0]["contents"]
        data_cells = rows[1]["contents"]

        self.assertEqual(header_cells[0]["attr"]["class"], "template-col")
        self.assertEqual(header_cells[1]["attr"]["class"], "wide-col")
        self.assertEqual(data_cells[0]["attr"]["class"], "template-col")
        self.assertEqual(data_cells[1]["attr"]["class"], "wide-col")

    def test_key_type_desc_table_applies_wide_last_col(self):
        table = tblh.key_type_desc_table([["header", "string", "Long description"]])

        rows = table["contents"]
        header_cells = rows[0]["contents"]
        data_cells = rows[1]["contents"]

        self.assertEqual(header_cells[2]["attr"]["class"], "wide-col")
        self.assertEqual(data_cells[2]["attr"]["class"], "wide-col")


